type ApiErrorCode int64

const (
	ApiErrorCodeRequestAlreadyUsed    ApiErrorCode = 1
	ApiErrorCodeRpKeyFetchFailed      ApiErrorCode = 2
	ApiErrorCodeRpEncryptKeyUntrusted ApiErrorCode = 3
	ApiErrorCodeSigningFailed         ApiErrorCode = 4
	ApiErrorCodeStorageFailed         ApiErrorCode = 5
	ApiErrorCodeBadRequest            ApiErrorCode = 6
	ApiErrorCodeUnauthorized          ApiErrorCode = 7
	ApiErrorCodeForbidden             ApiErrorCode = 8
	ApiErrorCodeNotFound              ApiErrorCode = 9
	ApiErrorCodeInternal              ApiErrorCode = 10
)

func (v ApiErrorCode) ToNumber() int64 {
	return int64(v)
}

func ApiErrorCodeFromNumber(number int64) (ApiErrorCode, error) {
	v := ApiErrorCode(number)
	switch v {
	case ApiErrorCodeRequestAlreadyUsed, ApiErrorCodeRpKeyFetchFailed, ApiErrorCodeRpEncryptKeyUntrusted, ApiErrorCodeSigningFailed, ApiErrorCodeStorageFailed, ApiErrorCodeBadRequest, ApiErrorCodeUnauthorized, ApiErrorCodeForbidden, ApiErrorCodeNotFound, ApiErrorCodeInternal:
		return v, nil
	}
	return 0, fmt.Errorf("unknown ApiErrorCode value %d", number)
}

func (v ApiErrorCode) MarshalText() ([]byte, error) {
	switch v {
	case ApiErrorCodeRequestAlreadyUsed:
		return []byte("request_already_used"), nil
	case ApiErrorCodeRpKeyFetchFailed:
		return []byte("rp_key_fetch_failed"), nil
	case ApiErrorCodeRpEncryptKeyUntrusted:
		return []byte("rp_encrypt_key_untrusted"), nil
	case ApiErrorCodeSigningFailed:
		return []byte("signing_failed"), nil
	case ApiErrorCodeStorageFailed:
		return []byte("storage_failed"), nil
	case ApiErrorCodeBadRequest:
		return []byte("bad_request"), nil
	case ApiErrorCodeUnauthorized:
		return []byte("unauthorized"), nil
	case ApiErrorCodeForbidden:
		return []byte("forbidden"), nil
	case ApiErrorCodeNotFound:
		return []byte("not_found"), nil
	case ApiErrorCodeInternal:
		return []byte("internal"), nil
	}
	return nil, fmt.Errorf("unknown ApiErrorCode value %d", v)
}

func (v *ApiErrorCode) UnmarshalText(text []byte) error {
	switch string(text) {
	case "request_already_used":
		*v = ApiErrorCodeRequestAlreadyUsed
	case "rp_key_fetch_failed":
		*v = ApiErrorCodeRpKeyFetchFailed
	case "rp_encrypt_key_untrusted":
		*v = ApiErrorCodeRpEncryptKeyUntrusted
	case "signing_failed":
		*v = ApiErrorCodeSigningFailed
	case "storage_failed":
		*v = ApiErrorCodeStorageFailed
	case "bad_request":
		*v = ApiErrorCodeBadRequest
	case "unauthorized":
		*v = ApiErrorCodeUnauthorized
	case "forbidden":
		*v = ApiErrorCodeForbidden
	case "not_found":
		*v = ApiErrorCodeNotFound
	case "internal":
		*v = ApiErrorCodeInternal
	default:
		return fmt.Errorf("unknown ApiErrorCode label %q", text)
	}
	return nil
}

